#!/usr/bin/env node
import {
	level,
	hasColor,
	hasBasic,
	has256,
	has16m,
	red,
	green,
	yellow,
	cyan,
	bold,
	dim,
} from '../index.js';

const args = process.argv.slice(2);

if (args.includes('--json')) {
	process.stdout.write(
		`${JSON.stringify({level, hasColor, hasBasic, has256, has16m}, null, 2)}\n`,
	);
	process.exit(0);
}

const status = hasColor
	? green(`color enabled (level ${level})`)
	: yellow('color disabled');

process.stdout.write(`${bold('color-cli')} ${dim('>')} ${status}\n`);

if (hasColor) {
	process.stdout.write(`${red('red')} ${green('green')} ${yellow('yellow')} ${cyan('cyan')}\n`);
} else {
	process.stdout.write('This terminal does not support colored output; printing plain text.\n');
}

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {fileURLToPath} from 'node:url';

const execFileAsync = promisify(execFile);
const cli = fileURLToPath(new URL('../bin/cli.js', import.meta.url));

const run = (env, args = []) =>
	execFileAsync(process.execPath, [cli, ...args], {env: {...process.env, ...env}});

test('emits ANSI escapes when FORCE_COLOR=1', async () => {
	const {stdout} = await run({FORCE_COLOR: '1'});
	assert.match(stdout, /\u001B\[/);
});

test('omits ANSI escapes when FORCE_COLOR=0', async () => {
	const {stdout} = await run({FORCE_COLOR: '0'});
	assert.doesNotMatch(stdout, /\u001B\[/);
});

test('--json reports the detected level', async () => {
	const {stdout} = await run({FORCE_COLOR: '2'}, ['--json']);
	assert.deepEqual(JSON.parse(stdout), {
		level: 2,
		hasColor: true,
		hasBasic: true,
		has256: true,
		has16m: false,
	});
});
